with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'أرصاد الطيران والأرصاد البحرية المتخصصة','منتجات الطيران والمطارات والرؤية وقص الرياح والاضطراب والجليد، والأرصاد البحرية والأمواج والمد العاصفي والخدمات الساحلية.',37,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'أرصاد الطيران والمطارات',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الأرصاد البحرية والملاحة',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('aviation-meteorology-foundations','أسس الأرصاد الجوية للطيران','عناصر الطقس المؤثرة في الطيران ومتطلبات المعلومات.','{"blocks":[{"type":"text","text":"يقدم الدرس أسس الأرصاد الجوية للطيران ضمن الخدمات الجوية المتخصصة التي تدعم سلامة الطيران أو الملاحة البحرية."},{"type":"text","text":"الأساس العلمي: عناصر الطقس المؤثرة في الطيران ومتطلبات المعلومات.، ويجب تفسير الحالة وفق الموقع والارتفاع أو المجال البحري والفترة التشغيلية."},{"type":"text","text":"تحدد احتياجات المستخدم ونوع العملية والمجال الجغرافي والمهلة الزمنية المطلوبة للمنتج."},{"type":"text","text":"تجمع المشاهدات المتخصصة والنماذج والرادار والأقمار والبلاغات التشغيلية مع توثيق وقت كل مصدر."},{"type":"text","text":"تراجع التعاريف والرموز والوحدات والمعايير المعتمدة للمنتج قبل إعداد النشرة أو تفسيرها."},{"type":"text","text":"تحلل الظاهرة في سياقها الديناميكي والحراري والرطوبي، مع مراعاة أثر التضاريس أو السطح البحري."},{"type":"text","text":"تحدد المناطق والفترات الأكثر تأثراً، وتفصل بين الرصد الحالي والتوقع المستقبلي."},{"type":"text","text":"توضح درجات الثقة والقيود ومصادر عدم اليقين التي قد تؤثر في القرار التشغيلي."},{"type":"text","text":"تنسق المعلومات مع الجهات المختصة وفق المسؤوليات والإجراءات المعتمدة دون تجاوز نطاق المنتج."},{"type":"text","text":"تراجع التوقعات بعد الحالة بمقارنتها بالمشاهدات والتقارير التشغيلية وتوثيق فرص التحسين."},{"type":"text","text":"مثال تطبيقي: إعداد إحاطة مختصرة تتضمن الحالة الحالية والمخاطر المتوقعة والتوقيت والمناطق والمنتجات المرجعية."},{"type":"callout","text":"الخلاصة: الخدمة الجوية المتخصصة تحتاج بيانات موثوقة ومصطلحات معيارية ورسالة واضحة مرتبطة باحتياج المستخدم."}]}',3760,55,'["تحديد الظواهر الجوية المؤثرة على القطاع","قراءة المنتجات التشغيلية ذات الصلة","إعداد إحاطة دقيقة ضمن المعايير المعتمدة"]','أرصاد الطيران والمطارات'),
('aviation-metar-decoding','قراءة وفك ترميز تقارير METAR','ترميز الرصد المطاري والاتجاهات والتغيرات.','{"blocks":[{"type":"text","text":"يقدم الدرس قراءة وفك ترميز تقارير METAR ضمن الخدمات الجوية المتخصصة التي تدعم سلامة الطيران أو الملاحة البحرية."},{"type":"text","text":"الأساس العلمي: ترميز الرصد المطاري والاتجاهات والتغيرات.، ويجب تفسير الحالة وفق الموقع والارتفاع أو المجال البحري والفترة التشغيلية."},{"type":"text","text":"تحدد احتياجات المستخدم ونوع العملية والمجال الجغرافي والمهلة الزمنية المطلوبة للمنتج."},{"type":"text","text":"تجمع المشاهدات المتخصصة والنماذج والرادار والأقمار والبلاغات التشغيلية مع توثيق وقت كل مصدر."},{"type":"text","text":"تراجع التعاريف والرموز والوحدات والمعايير المعتمدة للمنتج قبل إعداد النشرة أو تفسيرها."},{"type":"text","text":"تحلل الظاهرة في سياقها الديناميكي والحراري والرطوبي، مع مراعاة أثر التضاريس أو السطح البحري."},{"type":"text","text":"تحدد المناطق والفترات الأكثر تأثراً، وتفصل بين الرصد الحالي والتوقع المستقبلي."},{"type":"text","text":"توضح درجات الثقة والقيود ومصادر عدم اليقين التي قد تؤثر في القرار التشغيلي."},{"type":"text","text":"تنسق المعلومات مع الجهات المختصة وفق المسؤوليات والإجراءات المعتمدة دون تجاوز نطاق المنتج."},{"type":"text","text":"تراجع التوقعات بعد الحالة بمقارنتها بالمشاهدات والتقارير التشغيلية وتوثيق فرص التحسين."},{"type":"text","text":"مثال تطبيقي: إعداد إحاطة مختصرة تتضمن الحالة الحالية والمخاطر المتوقعة والتوقيت والمناطق والمنتجات المرجعية."},{"type":"callout","text":"الخلاصة: الخدمة الجوية المتخصصة تحتاج بيانات موثوقة ومصطلحات معيارية ورسالة واضحة مرتبطة باحتياج المستخدم."}]}',3770,55,'["تحديد الظواهر الجوية المؤثرة على القطاع","قراءة المنتجات التشغيلية ذات الصلة","إعداد إحاطة دقيقة ضمن المعايير المعتمدة"]','أرصاد الطيران والمطارات'),
